function Auth() {
    const url = "localhost:8000/"
    return ( 
        <>
        <form method="POST" action="/api/auth/users/">
        <p>Имя</p>
        <input type="text" name="username"/>
        <p>Почта</p>
        <input type="text" name="email"/>
        <p>Пароль</p>
        <input type="password" name="password"/>
        <button action="submit"></button>
        </form>
        </>
    );
}

export default Auth;
